const sendEmail = Effect.fn("sendEmail")(function* (title: string, report: string) {
  const apiKey = yield* findSecret("EMAIL_API_KEY")
  yield* Effect.tryPromise(() =>
    new EmailClient({ apiKey }).send({ title, body: report })
  )
})
